/* =====================================================================
   app2_2_read_procs_tests.sql   APP-2 stage 2: equipment search and detail read procedures, then their test
   GENERATED by tools/bundle_sql.py from the files listed below. Do not edit:
   change the source file and run `python tools/bundle_sql.py` again.
   Paste the whole file into New query of the ATLAS_SQL_DB item (type SQL database),
   run it once, and copy the Messages tab. Each file runs in its own batch.
   Files, in run order:
     db/procs/usp_equipment_search.sql
     db/procs/usp_equipment_detail.sql
     db/tests/t_equipment_read.sql
   ===================================================================== */
SET NOCOUNT ON;
PRINT N'=== app2_2_read_procs_tests: 3 file(s) ===';

PRINT N'--- db/procs/usp_equipment_search.sql';
EXEC (N'/* =====================================================================
   app.usp_equipment_search     APP-2, read path C (decided 15 Nov, D-17); screen S-4
   Single statement per file; CREATE OR ALTER, safe to run again.
   Called by the function searchEquipment. Needs app.vw_equipment_search.
   Test: db/tests/t_equipment_read.sql

   Why a procedure: the connector cannot read views (spike S7, 14-15 Nov), so the browser
   reaches the search view through a function that runs this procedure. The search RULES
   live here, not in the browser: which columns can be searched, the closest-match order,
   the row caps, the paging.

   One result set: the rows, in the column order of app.vw_equipment_search (29 columns).
   Three OUTPUT values describe it:
     @total_matches  SORTED: every heater that matches the text and facility (all pages).
                     MATCH:  the rows returned (after the caps).
     @has_more       SORTED: another page follows this one. MATCH: always 0.
     @truncated      MATCH: at least one closeness tier held more rows than its cap, so
                     there may be more matches than were returned. SORTED: always 0.

   @mode
     MATCH   a text was typed and no sort chosen: closest matches first (POC-APP-05).
             Tier 1 = the value equals the text, tier 2 = starts with it, tier 3 = merely
             contains it. Rows come tier by tier, each tier ordered by the searched column,
             then equipment number. Each tier is capped (200 / 500 / 500) so one broad text
             cannot return the whole table. @offset and @page_size are not used: the
             screen pages through the returned list itself.
     SORTED  one list in the order of a chosen column, read page by page with @offset and
             @page_size (1 to 100). A text, if there is one, is a "contains" filter.

   @search_column  one of the eight columns people can search (POC-APP-05); anything else
                   is refused. @sort_column may be any column of the view. Both are checked
                   against fixed lists or sys.columns and then written with QUOTENAME, and
                   every value goes in as a parameter, so no caller text becomes SQL.
   @facility       only heaters under this parent FLOC (the facility drill-down); empty = all.
   @filters_json   the boxes under the column headers of the screen (CR-1, 19 Nov): a JSON list
                   such as [{"column":"manufacturer","text":"abc"},{"column":"equip_class","text":"fired"}].
                   Every entry must match ("contains", AND), on top of @facility and @search_text,
                   in both modes. NULL, empty or [] = no column filters; an entry with a blank
                   text is ignored. The column must be one of the 20 text columns listed below
                   (@filter_cols); at most 20 entries, each text at most 100 characters. The list
                   is parsed once into escaped patterns and handed to the dynamic query as ONE
                   JSON parameter, so no caller text becomes SQL (column names come from the
                   fixed list, through QUOTENAME).

   The text is matched literally: % _ and [ typed by the person are escaped. Comparison
   follows the database collation (case-insensitive on this database). A heater whose value in
   a filtered column is blank (NULL) never matches a filter on that column.

   Paging is stable: every order ends with equipment_id, so a column that is not unique
   (manufacturer, say) never repeats or drops a heater between pages.

   Errors (THROW): 50010 view missing, 50011 bad mode, 50012 bad direction, 50013 bad
   offset or page size, 50014 column not searchable, 50015 MATCH without text, 50016 sort
   column unknown, 50017 @filters_json is not a JSON list of {column, text}, 50018 a filter
   column cannot be searched, 50019 more than 20 filters or a filter text over 100 characters.
   ===================================================================== */
CREATE OR ALTER PROCEDURE app.usp_equipment_search
    @mode           varchar(8),
    @search_column  varchar(40),
    @search_text    nvarchar(100) = N'''',
    @facility       nvarchar(40)  = N'''',
    @sort_column    varchar(40)   = ''equipment_number'',
    @sort_direction varchar(4)    = ''ASC'',
    @offset         int           = 0,
    @page_size      int           = 50,
    @filters_json   nvarchar(4000) = NULL,
    @total_matches  int OUTPUT,
    @has_more       bit OUTPUT,
    @truncated      bit OUTPUT
AS
BEGIN
    SET NOCOUNT ON;

    /* the rules in numbers */
    DECLARE @cap_exact    int = 200;
    DECLARE @cap_starts   int = 500;
    DECLARE @cap_contains int = 500;
    DECLARE @max_page     int = 100;

    DECLARE @view_id int = OBJECT_ID(N''app.vw_equipment_search'', N''V'');

    SET @mode           = UPPER(LTRIM(RTRIM(ISNULL(@mode, ''''))));
    SET @search_column  = LTRIM(RTRIM(ISNULL(@search_column, '''')));
    SET @search_text    = LTRIM(RTRIM(ISNULL(@search_text, N'''')));
    SET @facility       = LTRIM(RTRIM(ISNULL(@facility, N'''')));
    SET @sort_column    = LTRIM(RTRIM(ISNULL(@sort_column, '''')));
    SET @sort_direction = UPPER(LTRIM(RTRIM(ISNULL(@sort_direction, ''ASC''))));
    SET @offset         = ISNULL(@offset, 0);
    SET @page_size      = ISNULL(@page_size, 50);
    SET @filters_json   = LTRIM(RTRIM(ISNULL(@filters_json, N'''')));

    /* the text columns a person can filter on (the boxes under the headers); the screen''s list
       (columns.ts, FILTER_COLUMNS) must equal this one: a unit test compares them */
    DECLARE @filter_cols TABLE (col varchar(40) NOT NULL PRIMARY KEY);
    INSERT INTO @filter_cols (col) VALUES
        (''equipment_tag_number''), (''manufacturer_serial_number''), (''equipment_number''), (''functional_location''),
        (''superior_functional_location''), (''manufacturer''), (''equip_class''), (''profit_center_name''),
        (''equipment_description''), (''floc_description''), (''model_number''), (''fired_unfired''), (''class_type''),
        (''object_type''), (''floc_class''), (''tech_object_type''), (''equipment_user_status''), (''floc_user_status''),
        (''planner_group''), (''heater_population_method'');
    DECLARE @max_filters     int = 20;
    DECLARE @max_filter_text int = 100;

    SET @total_matches = 0;
    SET @has_more      = 0;
    SET @truncated     = 0;

    /* ---- checks ----------------------------------------------------------- */
    IF @view_id IS NULL
        THROW 50010, N''app.vw_equipment_search is missing: run the APP-2 views stage first.'', 1;
    IF @mode NOT IN (''MATCH'', ''SORTED'')
        THROW 50011, N''mode must be MATCH or SORTED.'', 1;
    IF @sort_direction NOT IN (''ASC'', ''DESC'')
        THROW 50012, N''sort direction must be ASC or DESC.'', 1;
    IF @offset < 0 OR @page_size < 1 OR @page_size > @max_page
        THROW 50013, N''offset must be 0 or more and page size 1 to 100.'', 1;
    IF @search_column NOT IN (''equipment_tag_number'', ''manufacturer_serial_number'', ''equipment_number'',
                              ''functional_location'', ''manufacturer'', ''equip_class'', ''floc_class'', ''profit_center_name'')
        THROW 50014, N''that column cannot be searched.'', 1;
    IF @mode = ''MATCH'' AND @search_text = N''''
        THROW 50015, N''MATCH needs a search text.'', 1;
    IF NOT EXISTS (SELECT 1 FROM sys.columns AS c WHERE c.object_id = @view_id AND c.name = @sort_column)
        THROW 50016, N''unknown sort column.'', 1;

    /* column filters: refuse a list that is not a JSON list of {column, text}, a column that is
       not on the fixed list, too many entries, or a text that is too long */
    DECLARE @fj nvarchar(max) = NULL;
    IF @filters_json <> N''''
    BEGIN
        IF ISJSON(@filters_json) <> 1 OR LEFT(@filters_json, 1) <> N''[''
            THROW 50017, N''filters must be a JSON list of {column, text}.'', 1;
        IF EXISTS (SELECT 1
                   FROM OPENJSON(@filters_json) WITH (col nvarchar(200) ''$.column'', txt nvarchar(1000) ''$.text'') AS f
                   WHERE f.col IS NULL OR f.txt IS NULL)
            THROW 50017, N''every filter needs a column and a text.'', 1;
        IF EXISTS (SELECT 1
                   FROM OPENJSON(@filters_json) WITH (col nvarchar(200) ''$.column'') AS f
                   WHERE f.col NOT IN (SELECT fc.col FROM @filter_cols AS fc))
            THROW 50018, N''a filter column cannot be searched.'', 1;
        IF (SELECT COUNT(*)
            FROM OPENJSON(@filters_json) WITH (txt nvarchar(1000) ''$.text'') AS f
            WHERE LTRIM(RTRIM(f.txt)) <> N'''') > @max_filters
           OR EXISTS (SELECT 1
                      FROM OPENJSON(@filters_json) WITH (txt nvarchar(1000) ''$.text'') AS f
                      WHERE LEN(LTRIM(RTRIM(f.txt))) > @max_filter_text)
            THROW 50019, N''at most 20 filters, each text at most 100 characters.'', 1;

        /* the escaped patterns, one JSON parameter for the dynamic query below (NULL when every
           text is blank). % _ [ and the escape character are escaped as for @search_text. */
        SELECT @fj = (SELECT f.col AS [col],
                             N''%'' + REPLACE(REPLACE(REPLACE(REPLACE(LTRIM(RTRIM(f.txt)), N''\'', N''\\''), N''%'', N''\%''), N''_'', N''\_''), N''['', N''\['') + N''%'' AS [pat]
                      FROM OPENJSON(@filters_json) WITH (col nvarchar(200) ''$.column'', txt nvarchar(1000) ''$.text'') AS f
                      WHERE LTRIM(RTRIM(f.txt)) <> N''''
                      FOR JSON PATH);
    END

    /* ---- the pieces of the query ------------------------------------------ */
    DECLARE @col  nvarchar(130) = QUOTENAME(@search_column);
    DECLARE @sort nvarchar(130) = QUOTENAME(@sort_column);
    DECLARE @dir  nvarchar(4)   = CASE WHEN @sort_direction = ''DESC'' THEN N''DESC'' ELSE N''ASC'' END;
    DECLARE @esc  nvarchar(400) = REPLACE(REPLACE(REPLACE(REPLACE(@search_text, N''\'', N''\\''), N''%'', N''\%''), N''_'', N''\_''), N''['', N''\['');

    /* every column of the view, in its own order (so the result follows the view) */
    DECLARE @cols nvarchar(max);
    SELECT @cols = STRING_AGG(CAST(QUOTENAME(c.name) AS nvarchar(max)), N'', '') WITHIN GROUP (ORDER BY c.column_id)
    FROM sys.columns AS c
    WHERE c.object_id = @view_id;

    DECLARE @filter nvarchar(max) = N''(@facility = N'''''''' OR v.superior_functional_location = @facility)'';
    IF @search_text <> N''''
        SET @filter = @filter + N'' AND v.'' + @col + N'' LIKE N''''%'''' + @esc + N''''%'''' ESCAPE N''''\'''''';

    /* the column filters: a heater passes when NO filter entry fails on it. For each entry the
       heater''s value in that entry''s column is picked with a CASE over the fixed column list
       (COLLATE DATABASE_DEFAULT so columns with different collations can share one CASE); a
       blank (NULL) value fails the entry, because the CASE then yields NULL and NULL LIKE is
       not a match. The patterns come from @fj, never from text pasted into the query. */
    IF @fj IS NOT NULL
    BEGIN
        DECLARE @pick nvarchar(max);
        SELECT @pick = N''CASE f.col '' + STRING_AGG(CAST(N''WHEN '''''' + fc.col + N'''''' THEN v.'' + QUOTENAME(fc.col) + N'' COLLATE DATABASE_DEFAULT'' AS nvarchar(max)), N'' '') + N'' END''
        FROM @filter_cols AS fc;
        SET @filter = @filter
            + N'' AND NOT EXISTS (SELECT 1 FROM OPENJSON(@fj) WITH (col varchar(40) ''''$.col'''', pat nvarchar(500) ''''$.pat'''') AS f''
            + N'' WHERE 1 = CASE WHEN ('' + @pick + N'') LIKE f.pat ESCAPE N''''\'''' THEN 0 ELSE 1 END)'';
    END

    DECLARE @sql nvarchar(max);
    DECLARE @n int = 0, @flag int = 0;

    DECLARE @p_count nvarchar(400) =
        N''@text nvarchar(100), @esc nvarchar(400), @facility nvarchar(40), @fj nvarchar(max), @cap1 int, @cap2 int, @cap3 int, @total int OUTPUT, @trunc int OUTPUT'';
    DECLARE @p_rows nvarchar(400) =
        N''@text nvarchar(100), @esc nvarchar(400), @facility nvarchar(40), @fj nvarchar(max), @cap1 int, @cap2 int, @cap3 int, @offset int, @page_size int'';

    /* ---- MATCH: closest first --------------------------------------------- */
    IF @mode = ''MATCH''
    BEGIN
        DECLARE @hits nvarchar(max) =
            N''WITH hits AS (SELECT v.*, CASE WHEN v.'' + @col + N'' = @text THEN 1''
            + N'' WHEN v.'' + @col + N'' LIKE @esc + N''''%'''' ESCAPE N''''\'''' THEN 2 ELSE 3 END AS tier''
            + N'' FROM app.vw_equipment_search AS v WHERE '' + @filter + N'')'';

        -- how many rows come back, and did any tier overflow its cap
        SET @sql = @hits
            + N'' SELECT @total = ISNULL(SUM(CASE t.tier WHEN 1 THEN CASE WHEN t.n > @cap1 THEN @cap1 ELSE t.n END''
            + N'' WHEN 2 THEN CASE WHEN t.n > @cap2 THEN @cap2 ELSE t.n END''
            + N'' ELSE CASE WHEN t.n > @cap3 THEN @cap3 ELSE t.n END END), 0),''
            + N'' @trunc = ISNULL(MAX(CASE WHEN (t.tier = 1 AND t.n > @cap1) OR (t.tier = 2 AND t.n > @cap2) OR (t.tier = 3 AND t.n > @cap3) THEN 1 ELSE 0 END), 0)''
            + N'' FROM (SELECT tier, COUNT(*) AS n FROM hits GROUP BY tier) AS t'';
        EXEC sp_executesql @sql, @p_count,
            @text = @search_text, @esc = @esc, @facility = @facility, @fj = @fj,
            @cap1 = @cap_exact, @cap2 = @cap_starts, @cap3 = @cap_contains,
            @total = @n OUTPUT, @trunc = @flag OUTPUT;
        SET @total_matches = @n;
        SET @truncated     = CASE WHEN @flag = 1 THEN 1 ELSE 0 END;

        -- the rows: tier by tier, each tier in the order of the searched column, then equipment
        -- number, then equipment id. A column may appear only once in an ORDER BY, so when the
        -- searched column IS the equipment number it is not listed a second time.
        DECLARE @ties_h nvarchar(100) = CASE WHEN @search_column = ''equipment_number'' THEN N''h.equipment_id'' ELSE N''h.equipment_number, h.equipment_id'' END;
        DECLARE @ties_r nvarchar(100) = CASE WHEN @search_column = ''equipment_number'' THEN N''r.equipment_id'' ELSE N''r.equipment_number, r.equipment_id'' END;
        SET @sql = @hits
            + N'', ranked AS (SELECT h.*, ROW_NUMBER() OVER (PARTITION BY h.tier ORDER BY h.'' + @col + N'', '' + @ties_h + N'') AS rn FROM hits AS h)''
            + N'' SELECT '' + @cols + N'' FROM ranked AS r''
            + N'' WHERE r.rn <= CASE r.tier WHEN 1 THEN @cap1 WHEN 2 THEN @cap2 ELSE @cap3 END''
            + N'' ORDER BY r.tier, r.'' + @col + N'', '' + @ties_r;
        EXEC sp_executesql @sql, @p_rows,
            @text = @search_text, @esc = @esc, @facility = @facility, @fj = @fj,
            @cap1 = @cap_exact, @cap2 = @cap_starts, @cap3 = @cap_contains,
            @offset = @offset, @page_size = @page_size;
        RETURN;
    END

    /* ---- SORTED: one column order, page by page ---------------------------- */
    SET @sql = N''SELECT @total = COUNT(*) FROM app.vw_equipment_search AS v WHERE '' + @filter;
    EXEC sp_executesql @sql, @p_count,
        @text = @search_text, @esc = @esc, @facility = @facility, @fj = @fj,
        @cap1 = @cap_exact, @cap2 = @cap_starts, @cap3 = @cap_contains,
        @total = @n OUTPUT, @trunc = @flag OUTPUT;
    SET @total_matches = @n;
    SET @has_more      = CASE WHEN @offset + @page_size < @n THEN 1 ELSE 0 END;

    SET @sql = N''SELECT '' + @cols + N'' FROM app.vw_equipment_search AS v WHERE '' + @filter
        + N'' ORDER BY v.'' + @sort + N'' '' + @dir
        + CASE WHEN @sort_column = ''equipment_id'' THEN N'''' ELSE N'', v.equipment_id'' END
        + N'' OFFSET @offset ROWS FETCH NEXT @page_size ROWS ONLY'';
    EXEC sp_executesql @sql, @p_rows,
        @text = @search_text, @esc = @esc, @facility = @facility, @fj = @fj,
        @cap1 = @cap_exact, @cap2 = @cap_starts, @cap3 = @cap_contains,
        @offset = @offset, @page_size = @page_size;
END
');

PRINT N'--- db/procs/usp_equipment_detail.sql';
EXEC (N'/* =====================================================================
   app.usp_equipment_detail     APP-2, read path C (decided 15 Nov, D-17); screen S-5
   Single statement per file; CREATE OR ALTER, safe to run again.
   Called by the function getEquipmentDetail. Reads only. Needs the gold views
   (gold.vw_equipment_current, gold.vw_floc_current, gold.vw_equipment_field_current;
   the synthetic stub or the data engineer''s real views) and app.vw_field_ownership.
   Test: db/tests/t_equipment_read.sql

   Everything the detail screen needs for ONE heater, in one call, so the function pays for
   one connection instead of five round trips. Four result sets, always in this order (an
   empty set when there is nothing to show):

     1  the heater           gold.vw_equipment_current, 0 or 1 row (0 = no such heater)
     2  its location         gold.vw_floc_current, the row of the heater''s functional location
     3  its field values     gold.vw_equipment_field_current, one row per catalogue field of the heater
     4  the field owners     app.vw_field_ownership, one row per active catalogue field
                             (the same for every heater; sent with it so the screen needs no second call)

   The catalogue itself (app.field_catalog) is a plain table the browser reads through the
   connector, so it is not repeated here.

   SELECT * is deliberate for the three gold views: they are the data engineer''s contract
   (FINAL PLAN/01 section 6.1, guarded by t_gold_contract.sql) and the function picks the
   columns it knows, so a column the engineer adds later changes nothing here.
   ===================================================================== */
CREATE OR ALTER PROCEDURE app.usp_equipment_detail
    @equipment_id int
AS
BEGIN
    SET NOCOUNT ON;

    SELECT e.*
    FROM gold.vw_equipment_current AS e
    WHERE e.equipment_id = @equipment_id;

    SELECT f.*
    FROM gold.vw_floc_current AS f
    WHERE f.functional_location =
          (SELECT e.functional_location FROM gold.vw_equipment_current AS e WHERE e.equipment_id = @equipment_id);

    SELECT x.*
    FROM gold.vw_equipment_field_current AS x
    WHERE x.equipment_id = @equipment_id;

    SELECT o.*
    FROM app.vw_field_ownership AS o;
END
');

PRINT N'--- db/tests/t_equipment_read.sql';
EXEC (N'/* =====================================================================
   t_equipment_read.sql      APP-2 test: app.usp_equipment_search and app.usp_equipment_detail
                             (read path C, decided 15 Nov, D-17)
   Needs : migrations 0001-0007, seeds 0101-0107, the gold views (the synthetic stub
           db/dev/gold_stub.sql or the data engineer''s real views), app.vw_field_ownership,
           app.vw_equipment_search and the two procedures.
   Changes nothing that stays: R8 edits four synthetic stub rows inside a transaction and
   ROLLS THEM BACK (it is skipped, with an INFO line, when the real gold has replaced the stub).
   Final line: `t_equipment_read RESULT: ...`

   Method: the rows of a call are captured into #r, which has an identity column `seq`, so the
   ORDER of the rows can be checked (a plain INSERT ... EXEC keeps no order a test may rely on).
   Expected values come from independent queries on app.vw_equipment_search, not from the
   procedure itself.

   Checks
     R1  both procedures exist; the search procedure returns the 29 columns of the view
     R2  SORTED, first page: the rows are the first 50 of the view in equipment-number order;
         @total_matches = all heaters, @has_more correct, @truncated = 0
     R3  SORTED, paging: page 2 continues exactly where page 1 stopped; the last page is short
         and has_more = 0; a page past the end is empty
     R4  SORTED on a column that is not unique (manufacturer, descending): two pages of 100 are
         exactly the first 200 of the view in that order (no repeats, no gaps)
     R5  facility filter: only heaters under that parent FLOC, and all of them
     R6  SORTED with a text: a "contains" filter, @total_matches equals the independent count
     R7  MATCH: the heaters whose tag contains the text, equal one first (synthetic heaters:
         tag SYN-TAG-0004 gives SYN-EQ-0004 alone, SYN-TAG-000 gives the 8 tagged heaters of
         0001-0009)
     R8  MATCH order: equal, then starts-with, each in column order, then contains
         (four synthetic stub rows, rolled back)
     R9  MATCH caps: a text that matches thousands of heaters returns at most 200 / 500 / 500
         rows per tier and says it was truncated
     R10 the text is literal: % _ [ typed by a person match only those characters
     R11 refusals: bad mode, direction, page size, offset, column, empty MATCH text, and a sort
         column that tries to inject SQL (errors 50011 to 50016)
     R12 usp_equipment_detail: first result set is the 26 contract columns, the procedure runs
         for a heater and for an unknown id, and its last set holds the field owners
     R13 column filters (CR-1, 19 Nov), two filters: the rows are exactly those that satisfy both
         (independent count), and it is AND, not OR (a second filter nothing satisfies empties the list)
     R14 column filters: blank entries and an empty list change nothing; 20 filters are accepted;
         a heater with a blank value never matches a filter on that column; % _ [ and \ are literal
     R15 column filters together with the facility, with the older single text, and in MATCH mode
     R16 column filter refusals: not JSON, not a list, missing column or text, a column off the
         list (also one that carries SQL), a text over 100 characters, 21 filters (50017 to 50019)
     R1 to R12 call the procedure without @filters_json (its default), so they also prove that the
     old call shape still works.
   ===================================================================== */
SET NOCOUNT ON;

IF CAST(SERVERPROPERTY(''EngineEdition'') AS int) = 11
   OR @@VERSION LIKE N''%Data Warehouse%''
   OR DB_NAME() NOT LIKE N''ATLAS[_]SQL[_]DB%''
BEGIN
    PRINT ''FAIL t_equipment_read wrong editor: connected to "'' + DB_NAME() + ''". Open the item named ATLAS_SQL_DB whose type is SQL database. Nothing was run.'';
    RETURN;
END
IF OBJECT_ID(N''app.usp_equipment_search'', N''P'') IS NULL OR OBJECT_ID(N''app.usp_equipment_detail'', N''P'') IS NULL
BEGIN
    PRINT ''FAIL t_equipment_read the procedures app.usp_equipment_search / app.usp_equipment_detail are missing: run the APP-2 read-procedures stage first. Nothing was run.'';
    RETURN;
END
IF OBJECT_ID(N''app.vw_equipment_search'', N''V'') IS NULL OR OBJECT_ID(N''app.vw_field_ownership'', N''V'') IS NULL
   OR OBJECT_ID(N''gold.vw_equipment_current'', N''V'') IS NULL OR OBJECT_ID(N''gold.vw_floc_current'', N''V'') IS NULL OR OBJECT_ID(N''gold.vw_equipment_field_current'', N''V'') IS NULL
BEGIN
    PRINT ''FAIL t_equipment_read a view is missing: run the APP-2 views stage and the gold stub (or the real gold) first. Nothing was run.'';
    RETURN;
END

DECLARE @checks int = 0, @fails int = 0;
DECLARE @t int, @m bit, @tr bit;                       -- the three OUTPUT values of the last call
DECLARE @n int, @n2 int, @nAll int, @total int, @lastOff int, @txt nvarchar(2000), @err int, @msg nvarchar(400);
DECLARE @collist nvarchar(max), @call nvarchar(max), @pdef nvarchar(max);

/* ---- helper: #r holds the rows of the last call, in arrival order (seq) ------- */
IF OBJECT_ID(N''tempdb..#r'') IS NOT NULL DROP TABLE #r;
SELECT IDENTITY(int, 1, 1) AS seq, * INTO #r FROM app.vw_equipment_search WHERE 1 = 0;

SELECT @collist = STRING_AGG(CAST(QUOTENAME(c.name) AS nvarchar(max)), N'', '') WITHIN GROUP (ORDER BY c.column_id)
FROM sys.columns AS c WHERE c.object_id = OBJECT_ID(N''app.vw_equipment_search'');

SET @call = N''TRUNCATE TABLE #r; INSERT INTO #r ('' + @collist + N'') EXEC app.usp_equipment_search''
    + N'' @mode = @p_mode, @search_column = @p_col, @search_text = @p_text, @facility = @p_fac,''
    + N'' @sort_column = @p_sort, @sort_direction = @p_dir, @offset = @p_off, @page_size = @p_size,''
    + N'' @total_matches = @o_total OUTPUT, @has_more = @o_more OUTPUT, @truncated = @o_trunc OUTPUT;'';
SET @pdef = N''@p_mode varchar(8), @p_col varchar(40), @p_text nvarchar(100), @p_fac nvarchar(40), @p_sort varchar(40), @p_dir varchar(4),''
    + N'' @p_off int, @p_size int, @o_total int OUTPUT, @o_more bit OUTPUT, @o_trunc bit OUTPUT'';

SELECT @total = COUNT(*) FROM app.vw_equipment_search;

/* ---- R1 columns ---------------------------------------------------------------- */
BEGIN TRY
    SET @checks += 1;
    EXEC sp_executesql @call, @pdef, @p_mode = ''SORTED'', @p_col = ''equipment_tag_number'', @p_text = N'''', @p_fac = N'''',
        @p_sort = ''equipment_number'', @p_dir = ''ASC'', @p_off = 0, @p_size = 50,
        @o_total = @t OUTPUT, @o_more = @m OUTPUT, @o_trunc = @tr OUTPUT;
    SELECT @n = COUNT(*) FROM #r;
    IF @n > 0 PRINT ''OK  R1 the search procedure returns the 29 columns of app.vw_equipment_search (an INSERT ... EXEC into that shape worked) and '' + CAST(@n AS varchar(10)) + '' row(s)'';
    ELSE BEGIN SET @fails += 1; PRINT ''FAIL R1 the search procedure returned no rows although the view has '' + CAST(@total AS varchar(10)); END
END TRY
BEGIN CATCH
    SET @fails += 1;
    PRINT ''FAIL R1 error '' + CAST(ERROR_NUMBER() AS varchar(12)) + '': '' + ERROR_MESSAGE();
END CATCH;

/* ---- R2 SORTED, first page ------------------------------------------------------ */
BEGIN TRY
    SET @checks += 1;
    EXEC sp_executesql @call, @pdef, @p_mode = ''SORTED'', @p_col = ''equipment_tag_number'', @p_text = N'''', @p_fac = N'''',
        @p_sort = ''equipment_number'', @p_dir = ''ASC'', @p_off = 0, @p_size = 50,
        @o_total = @t OUTPUT, @o_more = @m OUTPUT, @o_trunc = @tr OUTPUT;
    SELECT @n = COUNT(*) FROM #r;
    SELECT @n2 = COUNT(*)
    FROM #r AS r
    JOIN (SELECT equipment_id, ROW_NUMBER() OVER (ORDER BY equipment_number, equipment_id) AS rn FROM app.vw_equipment_search) AS o
      ON o.equipment_id = r.equipment_id AND o.rn = r.seq;
    IF @n = CASE WHEN @total < 50 THEN @total ELSE 50 END AND @n2 = @n AND @t = @total
       AND @m = CASE WHEN @total > 50 THEN 1 ELSE 0 END AND @tr = 0
        PRINT ''OK  R2 SORTED first page: '' + CAST(@n AS varchar(10)) + '' rows in equipment-number order, total '' + CAST(@t AS varchar(10)) + '', has_more '' + CAST(@m AS varchar(1)) + '', truncated 0'';
    ELSE
    BEGIN
        SET @fails += 1;
        PRINT ''FAIL R2 rows '' + CAST(@n AS varchar(10)) + '', rows in the expected place '' + CAST(@n2 AS varchar(10)) + '', total '' + ISNULL(CAST(@t AS varchar(10)), ''NULL'')
            + '' (view '' + CAST(@total AS varchar(10)) + ''), has_more '' + ISNULL(CAST(@m AS varchar(1)), ''NULL'') + '', truncated '' + ISNULL(CAST(@tr AS varchar(1)), ''NULL'');
    END
END TRY
BEGIN CATCH
    SET @fails += 1;
    PRINT ''FAIL R2 error '' + CAST(ERROR_NUMBER() AS varchar(12)) + '': '' + ERROR_MESSAGE();
END CATCH;

/* ---- R3 SORTED, paging ------------------------------------------------------------ */
BEGIN TRY
    SET @checks += 1;
    SET @txt = N'''';

    -- page 2 continues where page 1 stopped
    EXEC sp_executesql @call, @pdef, @p_mode = ''SORTED'', @p_col = ''equipment_tag_number'', @p_text = N'''', @p_fac = N'''',
        @p_sort = ''equipment_number'', @p_dir = ''ASC'', @p_off = 50, @p_size = 50,
        @o_total = @t OUTPUT, @o_more = @m OUTPUT, @o_trunc = @tr OUTPUT;
    SELECT @n = COUNT(*) FROM #r;
    SELECT @n2 = COUNT(*)
    FROM #r AS r
    JOIN (SELECT equipment_id, ROW_NUMBER() OVER (ORDER BY equipment_number, equipment_id) AS rn FROM app.vw_equipment_search) AS o
      ON o.equipment_id = r.equipment_id AND o.rn = 50 + r.seq;
    IF NOT (@n = CASE WHEN @total - 50 < 50 THEN CASE WHEN @total - 50 < 0 THEN 0 ELSE @total - 50 END ELSE 50 END AND @n2 = @n)
        SET @txt += N'' page 2: '' + CAST(@n2 AS nvarchar(10)) + N'' of '' + CAST(@n AS nvarchar(10)) + N'' rows in the expected place;'';

    -- last page: the last 7 heaters, nothing after them
    IF @total >= 7
    BEGIN
        SET @lastOff = @total - 7;   -- an argument of EXEC must be a variable or a constant, never an expression
        EXEC sp_executesql @call, @pdef, @p_mode = ''SORTED'', @p_col = ''equipment_tag_number'', @p_text = N'''', @p_fac = N'''',
            @p_sort = ''equipment_number'', @p_dir = ''ASC'', @p_off = @lastOff, @p_size = 50,
            @o_total = @t OUTPUT, @o_more = @m OUTPUT, @o_trunc = @tr OUTPUT;
        SELECT @n = COUNT(*) FROM #r;
        IF NOT (@n = 7 AND @m = 0 AND @t = @total)
            SET @txt += N'' last page: '' + CAST(@n AS nvarchar(10)) + N'' rows (expected 7), has_more '' + ISNULL(CAST(@m AS nvarchar(1)), N''NULL'') + N'';'';
    END

    -- a page past the end is empty
    EXEC sp_executesql @call, @pdef, @p_mode = ''SORTED'', @p_col = ''equipment_tag_number'', @p_text = N'''', @p_fac = N'''',
        @p_sort = ''equipment_number'', @p_dir = ''ASC'', @p_off = @total, @p_size = 50,
        @o_total = @t OUTPUT, @o_more = @m OUTPUT, @o_trunc = @tr OUTPUT;
    SELECT @n = COUNT(*) FROM #r;
    IF NOT (@n = 0 AND @m = 0 AND @t = @total)
        SET @txt += N'' past the end: '' + CAST(@n AS nvarchar(10)) + N'' rows (expected 0), has_more '' + ISNULL(CAST(@m AS nvarchar(1)), N''NULL'') + N'';'';

    IF @txt = N'''' PRINT ''OK  R3 paging: page 2 continues page 1, the last page is short with has_more 0, a page past the end is empty'';
    ELSE BEGIN SET @fails += 1; PRINT ''FAIL R3 paging:'' + @txt; END
END TRY
BEGIN CATCH
    SET @fails += 1;
    PRINT ''FAIL R3 error '' + CAST(ERROR_NUMBER() AS varchar(12)) + '': '' + ERROR_MESSAGE();
END CATCH;

/* ---- R4 SORTED on a column that is not unique -------------------------------------- */
BEGIN TRY
    SET @checks += 1;
    SET @txt = N'''';
    EXEC sp_executesql @call, @pdef, @p_mode = ''SORTED'', @p_col = ''equipment_tag_number'', @p_text = N'''', @p_fac = N'''',
        @p_sort = ''manufacturer'', @p_dir = ''DESC'', @p_off = 0, @p_size = 100,
        @o_total = @t OUTPUT, @o_more = @m OUTPUT, @o_trunc = @tr OUTPUT;
    SELECT @n = COUNT(*) FROM #r;
    SELECT @n2 = COUNT(*)
    FROM #r AS r
    JOIN (SELECT equipment_id, ROW_NUMBER() OVER (ORDER BY manufacturer DESC, equipment_id) AS rn FROM app.vw_equipment_search) AS o
      ON o.equipment_id = r.equipment_id AND o.rn = r.seq;
    IF NOT (@n = CASE WHEN @total < 100 THEN @total ELSE 100 END AND @n2 = @n)
        SET @txt += N'' page 1: '' + CAST(@n2 AS nvarchar(10)) + N'' of '' + CAST(@n AS nvarchar(10)) + N'' rows in the expected place;'';

    EXEC sp_executesql @call, @pdef, @p_mode = ''SORTED'', @p_col = ''equipment_tag_number'', @p_text = N'''', @p_fac = N'''',
        @p_sort = ''manufacturer'', @p_dir = ''DESC'', @p_off = 100, @p_size = 100,
        @o_total = @t OUTPUT, @o_more = @m OUTPUT, @o_trunc = @tr OUTPUT;
    SELECT @n = COUNT(*) FROM #r;
    SELECT @n2 = COUNT(*)
    FROM #r AS r
    JOIN (SELECT equipment_id, ROW_NUMBER() OVER (ORDER BY manufacturer DESC, equipment_id) AS rn FROM app.vw_equipment_search) AS o
      ON o.equipment_id = r.equipment_id AND o.rn = 100 + r.seq;
    IF NOT (@n = CASE WHEN @total - 100 < 100 THEN CASE WHEN @total - 100 < 0 THEN 0 ELSE @total - 100 END ELSE 100 END AND @n2 = @n)
        SET @txt += N'' page 2: '' + CAST(@n2 AS nvarchar(10)) + N'' of '' + CAST(@n AS nvarchar(10)) + N'' rows in the expected place;'';

    IF @txt = N'''' PRINT ''OK  R4 two pages sorted by manufacturer (descending, not unique) are exactly rows 1-200 of that order: no repeat, no gap'';
    ELSE BEGIN SET @fails += 1; PRINT ''FAIL R4 non-unique sort:'' + @txt; END
END TRY
BEGIN CATCH
    SET @fails += 1;
    PRINT ''FAIL R4 error '' + CAST(ERROR_NUMBER() AS varchar(12)) + '': '' + ERROR_MESSAGE();
END CATCH;

/* ---- R5 facility filter --------------------------------------------------------------- */
DECLARE @fac nvarchar(40);
SELECT TOP (1) @fac = superior_functional_location
FROM app.vw_equipment_search
WHERE superior_functional_location IS NOT NULL
ORDER BY equipment_id;

BEGIN TRY
    IF @fac IS NULL
        PRINT ''INFO R5 no heater has a parent FLOC: the facility check is skipped'';
    ELSE
    BEGIN
        SET @checks += 1;
        EXEC sp_executesql @call, @pdef, @p_mode = ''SORTED'', @p_col = ''equipment_tag_number'', @p_text = N'''', @p_fac = @fac,
            @p_sort = ''equipment_number'', @p_dir = ''ASC'', @p_off = 0, @p_size = 100,
            @o_total = @t OUTPUT, @o_more = @m OUTPUT, @o_trunc = @tr OUTPUT;
        SELECT @n = COUNT(*) FROM #r;
        SELECT @n2 = COUNT(*) FROM #r WHERE superior_functional_location = @fac;
        SELECT @total = COUNT(*) FROM app.vw_equipment_search WHERE superior_functional_location = @fac;
        IF @n2 = @n AND @t = @total AND @n = CASE WHEN @total < 100 THEN @total ELSE 100 END
            PRINT ''OK  R5 facility filter: '' + CAST(@t AS varchar(10)) + '' heater(s) under '' + @fac + '', every returned row is under it'';
        ELSE
        BEGIN
            SET @fails += 1;
            PRINT ''FAIL R5 facility '' + @fac + '': total '' + ISNULL(CAST(@t AS varchar(10)), ''NULL'') + '' (expected '' + CAST(@total AS varchar(10)) + ''), rows '' + CAST(@n AS varchar(10)) + '', rows under it '' + CAST(@n2 AS varchar(10));
        END
        SELECT @total = COUNT(*) FROM app.vw_equipment_search;
    END
END TRY
BEGIN CATCH
    SET @fails += 1;
    PRINT ''FAIL R5 error '' + CAST(ERROR_NUMBER() AS varchar(12)) + '': '' + ERROR_MESSAGE();
END CATCH;

/* ---- R6 SORTED with a text ---------------------------------------------------------------- */
BEGIN TRY
    SET @checks += 1;
    SELECT @n = COUNT(*) FROM app.vw_equipment_search WHERE equipment_tag_number LIKE N''%SYN-TAG-000%'';
    EXEC sp_executesql @call, @pdef, @p_mode = ''SORTED'', @p_col = ''equipment_tag_number'', @p_text = N''SYN-TAG-000'', @p_fac = N'''',
        @p_sort = ''equipment_number'', @p_dir = ''ASC'', @p_off = 0, @p_size = 100,
        @o_total = @t OUTPUT, @o_more = @m OUTPUT, @o_trunc = @tr OUTPUT;
    SELECT @n2 = COUNT(*) FROM #r WHERE equipment_tag_number LIKE N''%SYN-TAG-000%'';
    SELECT @nAll = COUNT(*) FROM #r;
    IF @t = @n AND @n2 = @nAll AND @n2 = CASE WHEN @n < 100 THEN @n ELSE 100 END
        PRINT ''OK  R6 SORTED with a text is a "contains" filter: '' + CAST(@t AS varchar(10)) + '' match(es) for SYN-TAG-000, every returned tag contains it'';
    ELSE
    BEGIN
        SET @fails += 1;
        PRINT ''FAIL R6 total '' + ISNULL(CAST(@t AS varchar(10)), ''NULL'') + '' (independent count '' + CAST(@n AS varchar(10)) + ''), returned rows that contain the text '' + CAST(@n2 AS varchar(10)) + '' of '' + CAST(@nAll AS varchar(10));
    END
END TRY
BEGIN CATCH
    SET @fails += 1;
    PRINT ''FAIL R6 error '' + CAST(ERROR_NUMBER() AS varchar(12)) + '': '' + ERROR_MESSAGE();
END CATCH;

/* ---- R7 MATCH ---------------------------------------------------------------------------------- */
DECLARE @synA int, @synB int;
SELECT @synA = COUNT(*) FROM gold.vw_equipment_current WHERE equipment_number = N''SYN-EQ-0004'' AND equipment_tag_number = N''SYN-TAG-0004'';
SELECT @synB = COUNT(*) FROM gold.vw_equipment_current WHERE equipment_number BETWEEN N''SYN-EQ-0001'' AND N''SYN-EQ-0009'';

BEGIN TRY
    SET @checks += 1;
    SET @txt = N'''';

    -- generic: every heater whose tag contains the text comes back (below the caps), none other
    SELECT @n = COUNT(*) FROM app.vw_equipment_search WHERE equipment_tag_number LIKE N''%SYN-TAG-000%'';
    EXEC sp_executesql @call, @pdef, @p_mode = ''MATCH'', @p_col = ''equipment_tag_number'', @p_text = N''SYN-TAG-000'', @p_fac = N'''',
        @p_sort = ''equipment_number'', @p_dir = ''ASC'', @p_off = 0, @p_size = 50,
        @o_total = @t OUTPUT, @o_more = @m OUTPUT, @o_trunc = @tr OUTPUT;
    SELECT @n2 = COUNT(*) FROM #r;
    IF NOT (@n2 = @n AND @t = @n AND @m = 0 AND @tr = 0)
        SET @txt += N'' SYN-TAG-000: '' + CAST(@n2 AS nvarchar(10)) + N'' rows, total '' + ISNULL(CAST(@t AS nvarchar(10)), N''NULL'') + N'' (independent count '' + CAST(@n AS nvarchar(10)) + N'');'';
    IF @synB = 9
    BEGIN
        -- the nine synthetic heaters 0001-0009 have 8 tags (0007 has none); nothing else in the stub starts that way
        SELECT @n = COUNT(*) FROM #r WHERE equipment_tag_number LIKE N''SYN-TAG-000%'';
        IF NOT (@n = 8) SET @txt += N'' synthetic: '' + CAST(@n AS nvarchar(10)) + N'' tags start with SYN-TAG-000 (expected 8);'';
    END

    -- synthetic: an exact tag gives that heater alone
    IF @synA = 1
    BEGIN
        EXEC sp_executesql @call, @pdef, @p_mode = ''MATCH'', @p_col = ''equipment_tag_number'', @p_text = N''SYN-TAG-0004'', @p_fac = N'''',
            @p_sort = ''equipment_number'', @p_dir = ''ASC'', @p_off = 0, @p_size = 50,
            @o_total = @t OUTPUT, @o_more = @m OUTPUT, @o_trunc = @tr OUTPUT;
        SELECT @n = COUNT(*) FROM #r;
        SELECT @n2 = COUNT(*) FROM #r WHERE seq = 1 AND equipment_number = N''SYN-EQ-0004'';
        IF NOT (@n = 1 AND @n2 = 1 AND @t = 1) SET @txt += N'' SYN-TAG-0004: '' + CAST(@n AS nvarchar(10)) + N'' row(s), first is SYN-EQ-0004: '' + CAST(@n2 AS nvarchar(10)) + N'';'';
    END
    ELSE PRINT ''INFO R7 the synthetic heater SYN-EQ-0004 is not in gold (real gold is loaded): the exact-tag part is skipped'';

    IF @txt = N'''' PRINT ''OK  R7 MATCH returns the matching heaters (and, for the synthetic stub, SYN-TAG-0004 gives SYN-EQ-0004 alone)'';
    ELSE BEGIN SET @fails += 1; PRINT ''FAIL R7 MATCH:'' + @txt; END
END TRY
BEGIN CATCH
    SET @fails += 1;
    PRINT ''FAIL R7 error '' + CAST(ERROR_NUMBER() AS varchar(12)) + '': '' + ERROR_MESSAGE();
END CATCH;

/* ---- R8 MATCH order: equal, starts-with (in column order), contains --------------------------- */
DECLARE @orderNow nvarchar(400), @stubVisible int;
BEGIN TRY
    IF OBJECT_ID(N''dev.stub_equipment'', N''U'') IS NULL OR
       (SELECT COUNT(*) FROM gold.vw_equipment_current WHERE equipment_number IN (N''SYN-EQ-0001'', N''SYN-EQ-0002'', N''SYN-EQ-0003'', N''SYN-EQ-0004'')) <> 4
        PRINT ''INFO R8 the synthetic stub is not the gold source here: the closest-match order check is skipped'';
    ELSE
    BEGIN
        SET @checks += 1;
        BEGIN TRANSACTION;

        UPDATE dev.stub_equipment SET equipment_tag_number = N''ZTAGPROBE''   WHERE equipment_number = N''SYN-EQ-0001'';   -- equals the text
        UPDATE dev.stub_equipment SET equipment_tag_number = N''ZTAGPROBE-X'' WHERE equipment_number = N''SYN-EQ-0002'';   -- starts with it
        UPDATE dev.stub_equipment SET equipment_tag_number = N''A-ZTAGPROBE'' WHERE equipment_number = N''SYN-EQ-0003'';   -- only contains it
        UPDATE dev.stub_equipment SET equipment_tag_number = N''ZTAGPROBE-A'' WHERE equipment_number = N''SYN-EQ-0004'';   -- starts with it, sorts before -X

        SELECT @stubVisible = COUNT(*) FROM gold.vw_equipment_current WHERE equipment_tag_number = N''ZTAGPROBE'';
        IF @stubVisible = 1
        BEGIN
            EXEC sp_executesql @call, @pdef, @p_mode = ''MATCH'', @p_col = ''equipment_tag_number'', @p_text = N''ZTAGPROBE'', @p_fac = N'''',
                @p_sort = ''equipment_number'', @p_dir = ''ASC'', @p_off = 0, @p_size = 50,
                @o_total = @t OUTPUT, @o_more = @m OUTPUT, @o_trunc = @tr OUTPUT;
            SELECT @orderNow = STRING_AGG(CAST(equipment_number AS nvarchar(40)), N'','') WITHIN GROUP (ORDER BY seq) FROM #r;
        END
        ROLLBACK TRANSACTION;

        IF @stubVisible <> 1
        BEGIN
            SET @checks -= 1;
            PRINT ''INFO R8 the gold views do not read dev.stub_equipment (the real gold is loaded): the closest-match order check is skipped'';
        END
        ELSE IF @orderNow = N''SYN-EQ-0001,SYN-EQ-0004,SYN-EQ-0002,SYN-EQ-0003'' AND @t = 4
            PRINT ''OK  R8 closest first: equal (0001), then starts-with in column order (0004 ZTAGPROBE-A before 0002 ZTAGPROBE-X), then contains (0003)'';
        ELSE
        BEGIN
            SET @fails += 1;
            PRINT ''FAIL R8 order is '' + ISNULL(@orderNow, N''(none)'') + '' with total '' + ISNULL(CAST(@t AS nvarchar(10)), N''NULL'') + ''; expected SYN-EQ-0001,SYN-EQ-0004,SYN-EQ-0002,SYN-EQ-0003 and total 4'';
        END
    END
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    SET @fails += 1;
    PRINT ''FAIL R8 error '' + CAST(ERROR_NUMBER() AS varchar(12)) + '' on line '' + CAST(ERROR_LINE() AS varchar(12)) + '': '' + ERROR_MESSAGE() + '' (the transaction was rolled back)'';
END CATCH;

/* ---- R9 MATCH caps ------------------------------------------------------------------------------ */
BEGIN TRY
    SET @checks += 1;
    DECLARE @expRows int, @expTrunc int, @t1 int, @t2 int, @t3 int;

    -- independent per-tier counts of the heaters whose class contains HEATER
    ;WITH x AS (
        SELECT CASE WHEN equip_class = N''HEATER'' THEN 1 WHEN equip_class LIKE N''HEATER%'' THEN 2 ELSE 3 END AS tier
        FROM app.vw_equipment_search
        WHERE equip_class LIKE N''%HEATER%''
    ), g AS (
        SELECT tier, COUNT(*) AS cnt FROM x GROUP BY tier
    )
    SELECT @expRows  = ISNULL(SUM(CASE tier WHEN 1 THEN IIF(cnt > 200, 200, cnt) ELSE IIF(cnt > 500, 500, cnt) END), 0),
           @expTrunc = ISNULL(MAX(CASE WHEN (tier = 1 AND cnt > 200) OR (tier > 1 AND cnt > 500) THEN 1 ELSE 0 END), 0)
    FROM g;

    EXEC sp_executesql @call, @pdef, @p_mode = ''MATCH'', @p_col = ''equip_class'', @p_text = N''HEATER'', @p_fac = N'''',
        @p_sort = ''equipment_number'', @p_dir = ''ASC'', @p_off = 0, @p_size = 50,
        @o_total = @t OUTPUT, @o_more = @m OUTPUT, @o_trunc = @tr OUTPUT;
    SELECT @n = COUNT(*) FROM #r;
    SELECT @t1 = COUNT(*) FROM #r WHERE equip_class = N''HEATER'';
    SELECT @t2 = COUNT(*) FROM #r WHERE equip_class LIKE N''HEATER%'' AND equip_class <> N''HEATER'';
    SELECT @t3 = COUNT(*) FROM #r WHERE equip_class NOT LIKE N''HEATER%'';
    IF @n = @expRows AND @t = @expRows AND @tr = @expTrunc AND @t1 <= 200 AND @t2 <= 500 AND @t3 <= 500
        PRINT ''OK  R9 caps: '' + CAST(@n AS varchar(10)) + '' rows for class HEATER (tiers '' + CAST(@t1 AS varchar(10)) + '' / '' + CAST(@t2 AS varchar(10)) + '' / '' + CAST(@t3 AS varchar(10)) + ''), truncated '' + CAST(@tr AS varchar(1)) + '', as the independent count expects'';
    ELSE
    BEGIN
        SET @fails += 1;
        PRINT ''FAIL R9 caps: rows '' + CAST(@n AS varchar(10)) + '' (expected '' + CAST(@expRows AS varchar(10)) + ''), total '' + ISNULL(CAST(@t AS varchar(10)), ''NULL'')
            + '', truncated '' + ISNULL(CAST(@tr AS varchar(1)), ''NULL'') + '' (expected '' + CAST(@expTrunc AS varchar(1)) + ''), tiers '' + CAST(@t1 AS varchar(10)) + '' / '' + CAST(@t2 AS varchar(10)) + '' / '' + CAST(@t3 AS varchar(10));
    END
END TRY
BEGIN CATCH
    SET @fails += 1;
    PRINT ''FAIL R9 error '' + CAST(ERROR_NUMBER() AS varchar(12)) + '': '' + ERROR_MESSAGE();
END CATCH;

/* ---- R10 the text is literal --------------------------------------------------------------------- */
BEGIN TRY
    SET @checks += 1;
    SET @txt = N'''';

    -- ''%'' typed by a person is a percent sign, not "anything"
    SELECT @n = COUNT(*) FROM app.vw_equipment_search WHERE CHARINDEX(N''%'', equipment_tag_number) > 0;
    EXEC sp_executesql @call, @pdef, @p_mode = ''MATCH'', @p_col = ''equipment_tag_number'', @p_text = N''%'', @p_fac = N'''',
        @p_sort = ''equipment_number'', @p_dir = ''ASC'', @p_off = 0, @p_size = 50,
        @o_total = @t OUTPUT, @o_more = @m OUTPUT, @o_trunc = @tr OUTPUT;
    SELECT @n2 = COUNT(*) FROM #r;
    IF NOT (@n2 = @n) SET @txt += N'' % gave '' + CAST(@n2 AS nvarchar(10)) + N'' rows, expected '' + CAST(@n AS nvarchar(10)) + N'';'';

    -- ''_'' is an underscore, not "any one character"
    SELECT @n = COUNT(*) FROM app.vw_equipment_search WHERE CHARINDEX(N''_'', equipment_tag_number) > 0;
    EXEC sp_executesql @call, @pdef, @p_mode = ''SORTED'', @p_col = ''equipment_tag_number'', @p_text = N''_'', @p_fac = N'''',
        @p_sort = ''equipment_number'', @p_dir = ''ASC'', @p_off = 0, @p_size = 100,
        @o_total = @t OUTPUT, @o_more = @m OUTPUT, @o_trunc = @tr OUTPUT;
    IF NOT (@t = @n) SET @txt += N'' _ counted '' + ISNULL(CAST(@t AS nvarchar(10)), N''NULL'') + N'', expected '' + CAST(@n AS nvarchar(10)) + N'';'';

    -- ''['' does not open a character class (an unescaped ''['' would make the pattern invalid or match anything)
    EXEC sp_executesql @call, @pdef, @p_mode = ''SORTED'', @p_col = ''equipment_tag_number'', @p_text = N''[SYN'', @p_fac = N'''',
        @p_sort = ''equipment_number'', @p_dir = ''ASC'', @p_off = 0, @p_size = 100,
        @o_total = @t OUTPUT, @o_more = @m OUTPUT, @o_trunc = @tr OUTPUT;
    SELECT @n2 = COUNT(*) FROM app.vw_equipment_search WHERE CHARINDEX(N''[SYN'', equipment_tag_number) > 0;
    IF NOT (@t = @n2) SET @txt += N'' [SYN counted '' + ISNULL(CAST(@t AS nvarchar(10)), N''NULL'') + N'', expected '' + CAST(@n2 AS nvarchar(10)) + N'';'';

    IF @txt = N'''' PRINT ''OK  R10 % _ and [ typed by a person are matched as those characters only'';
    ELSE BEGIN SET @fails += 1; PRINT ''FAIL R10 literal text:'' + @txt; END
END TRY
BEGIN CATCH
    SET @fails += 1;
    PRINT ''FAIL R10 error '' + CAST(ERROR_NUMBER() AS varchar(12)) + '': '' + ERROR_MESSAGE();
END CATCH;

/* ---- R11 refusals ----------------------------------------------------------------------------------- */
DECLARE @bad TABLE (n int IDENTITY(1,1), label varchar(60), call_mode varchar(8), search_col varchar(40), search_txt nvarchar(100), sort_col varchar(40), sort_dir varchar(10), start_row int, rows_per_page int, expected_error int);
INSERT INTO @bad (label, call_mode, search_col, search_txt, sort_col, sort_dir, start_row, rows_per_page, expected_error) VALUES
    (''bad mode'',                 ''FIND'',   ''equipment_tag_number'', N''x'', ''equipment_number'', ''ASC'',      0, 50,  50011),
    (''bad direction'',            ''SORTED'', ''equipment_tag_number'', N''x'', ''equipment_number'', ''SIDEWAYS'', 0, 50,  50012),
    (''page size 0'',              ''SORTED'', ''equipment_tag_number'', N''x'', ''equipment_number'', ''ASC'',      0, 0,   50013),
    (''page size 101'',            ''SORTED'', ''equipment_tag_number'', N''x'', ''equipment_number'', ''ASC'',      0, 101, 50013),
    (''negative offset'',          ''SORTED'', ''equipment_tag_number'', N''x'', ''equipment_number'', ''ASC'',     -1, 50,  50013),
    (''column not searchable'',    ''SORTED'', ''equipment_id'',         N''x'', ''equipment_number'', ''ASC'',      0, 50,  50014),
    (''MATCH without a text'',     ''MATCH'',  ''equipment_tag_number'', N'''',  ''equipment_number'', ''ASC'',      0, 50,  50015),
    (''unknown sort column'',      ''SORTED'', ''equipment_tag_number'', N''x'', ''no_such_column'',   ''ASC'',      0, 50,  50016),
    (''sort column with SQL'',     ''SORTED'', ''equipment_tag_number'', N''x'', ''equipment_id;DROP TABLE app.app_setting'', ''ASC'', 0, 50, 50016);

DECLARE @i int = 1, @maxBad int = (SELECT COUNT(*) FROM @bad);
DECLARE @bLabel varchar(60), @bMode varchar(8), @bCol varchar(40), @bTxt nvarchar(100), @bSrt varchar(40), @bDir varchar(4), @bOff int, @bSz int, @bExpect int;
DECLARE @refused int = 0, @refuseProblems nvarchar(1500) = N'''';

SET @checks += 1;
WHILE @i <= @maxBad
BEGIN
    SELECT @bLabel = label, @bMode = call_mode, @bCol = search_col, @bTxt = search_txt, @bSrt = sort_col, @bDir = sort_dir,
           @bOff = start_row, @bSz = rows_per_page, @bExpect = expected_error
    FROM @bad WHERE n = @i;
    SET @err = NULL;
    BEGIN TRY
        EXEC sp_executesql @call, @pdef, @p_mode = @bMode, @p_col = @bCol, @p_text = @bTxt, @p_fac = N'''',
            @p_sort = @bSrt, @p_dir = @bDir, @p_off = @bOff, @p_size = @bSz,
            @o_total = @t OUTPUT, @o_more = @m OUTPUT, @o_trunc = @tr OUTPUT;
    END TRY
    BEGIN CATCH
        SET @err = ERROR_NUMBER();
    END CATCH;
    IF @err = @bExpect SET @refused += 1;
    ELSE SET @refuseProblems += N'' ['' + @bLabel + N'': error '' + ISNULL(CAST(@err AS nvarchar(12)), N''none'') + N'', expected '' + CAST(@bExpect AS nvarchar(12)) + N'']'';
    SET @i += 1;
END

IF OBJECT_ID(N''app.app_setting'', N''U'') IS NULL
    SET @refuseProblems += N'' [app.app_setting is gone: the injection attempt may have worked]'';

IF @refused = @maxBad AND @refuseProblems = N''''
    PRINT ''OK  R11 all '' + CAST(@maxBad AS varchar(10)) + '' bad calls are refused with the expected error number (50011 to 50016), including a sort column that carries SQL'';
ELSE BEGIN SET @fails += 1; PRINT ''FAIL R11 refusals:'' + @refuseProblems; END

/* ---- R12 usp_equipment_detail ------------------------------------------------------------------------- */
DECLARE @heaterId int, @owners int, @rc1 int, @rc2 int;
SELECT TOP (1) @heaterId = equipment_id FROM gold.vw_equipment_current ORDER BY equipment_id;
SELECT @owners = COUNT(*) FROM app.vw_field_ownership;

BEGIN TRY
    SET @checks += 1;
    SET @txt = N'''';

    -- the first result set is the heater: the 26 contract columns
    SELECT @n = COUNT(*)
    FROM sys.dm_exec_describe_first_result_set_for_object(OBJECT_ID(N''app.usp_equipment_detail''), NULL) AS d
    WHERE d.error_message IS NULL;
    SELECT @n2 = COUNT(*)
    FROM sys.dm_exec_describe_first_result_set(N''SELECT * FROM gold.vw_equipment_current'', NULL, 0) AS g
    JOIN sys.dm_exec_describe_first_result_set_for_object(OBJECT_ID(N''app.usp_equipment_detail''), NULL) AS d
      ON d.name COLLATE Latin1_General_BIN2 = g.name COLLATE Latin1_General_BIN2 AND d.system_type_name = g.system_type_name;
    IF NOT (@n >= 26 AND @n2 = @n) SET @txt += N'' the first result set has '' + CAST(@n AS nvarchar(10)) + N'' columns, '' + CAST(@n2 AS nvarchar(10)) + N'' equal to gold.vw_equipment_current;'';

    -- it runs for a heater and for an unknown id; its last set (the owners) is always sent
    EXEC app.usp_equipment_detail @equipment_id = @heaterId;
    SET @rc1 = @@ROWCOUNT;
    EXEC app.usp_equipment_detail @equipment_id = -1;
    SET @rc2 = @@ROWCOUNT;
    IF NOT (@rc1 = @owners AND @rc2 = @owners) SET @txt += N'' last set had '' + CAST(@rc1 AS nvarchar(10)) + N'' / '' + CAST(@rc2 AS nvarchar(10)) + N'' row(s), expected '' + CAST(@owners AS nvarchar(10)) + N'';'';

    IF @txt = N'''' PRINT ''OK  R12 usp_equipment_detail: heater columns match gold, it runs for a heater and for an unknown id, and sends the '' + CAST(@owners AS varchar(10)) + '' field owner row(s) every time'';
    ELSE BEGIN SET @fails += 1; PRINT ''FAIL R12 usp_equipment_detail:'' + @txt; END
END TRY
BEGIN CATCH
    SET @fails += 1;
    PRINT ''FAIL R12 error '' + CAST(ERROR_NUMBER() AS varchar(12)) + '': '' + ERROR_MESSAGE();
END CATCH;

/* ---- R13 to R16: the column filters (CR-1) ---------------------------------------------------------
   The same call with @filters_json. Expected values come from independent counts on the view that use
   CHARINDEX (a literal "contains"; a blank value never matches), not from the procedure''s own LIKE. */
DECLARE @callF nvarchar(max), @pdefF nvarchar(max);
SET @callF = REPLACE(@call, N''@page_size = @p_size,'', N''@page_size = @p_size, @filters_json = @p_filters,'');
SET @pdefF = REPLACE(@pdef, N''@p_off int, @p_size int,'', N''@p_off int, @p_size int, @p_filters nvarchar(4000),'');

DECLARE @fa nvarchar(100), @fb nvarchar(100), @ft nvarchar(100), @fJson nvarchar(4000);
DECLARE @cA int, @cAB int, @allRows int, @k int, @kMax int, @ch nvarchar(4);
SELECT @allRows = COUNT(*) FROM app.vw_equipment_search;

-- the first word of a manufacturer, of an equipment class and of a tag (no spaces, so trimming cannot change it)
SELECT TOP (1)
       @fa = LEFT(LTRIM(manufacturer), CHARINDEX(N'' '', LTRIM(manufacturer) + N'' '') - 1),
       @fb = LEFT(LTRIM(equip_class), CHARINDEX(N'' '', LTRIM(equip_class) + N'' '') - 1)
FROM app.vw_equipment_search
WHERE LTRIM(manufacturer) <> N'''' AND LTRIM(equip_class) <> N''''
ORDER BY equipment_id;
SELECT TOP (1) @ft = LEFT(LTRIM(equipment_tag_number), CHARINDEX(N'' '', LTRIM(equipment_tag_number) + N'' '') - 1)
FROM app.vw_equipment_search
WHERE LTRIM(equipment_tag_number) <> N''''
ORDER BY equipment_id;

/* ---- R13 two filters, AND ------------------------------------------------------------------------------ */
BEGIN TRY
    IF @fa IS NULL OR @fb IS NULL
        PRINT ''INFO R13 no heater has both a manufacturer and an equipment class: the filter check is skipped'';
    ELSE
    BEGIN
        SET @checks += 1;
        SET @txt = N'''';

        -- two filters: exactly the heaters that satisfy both
        SET @fJson = N''[{"column":"manufacturer","text":"'' + STRING_ESCAPE(@fa, ''json'') + N''"},{"column":"equip_class","text":"'' + STRING_ESCAPE(@fb, ''json'') + N''"}]'';
        SELECT @cAB = COUNT(*) FROM app.vw_equipment_search WHERE CHARINDEX(@fa, manufacturer) > 0 AND CHARINDEX(@fb, equip_class) > 0;
        EXEC sp_executesql @callF, @pdefF, @p_mode = ''SORTED'', @p_col = ''equipment_tag_number'', @p_text = N'''', @p_fac = N'''',
            @p_sort = ''equipment_number'', @p_dir = ''ASC'', @p_off = 0, @p_size = 100, @p_filters = @fJson,
            @o_total = @t OUTPUT, @o_more = @m OUTPUT, @o_trunc = @tr OUTPUT;
        SELECT @n = COUNT(*) FROM #r;
        SELECT @n2 = COUNT(*) FROM #r WHERE CHARINDEX(@fa, manufacturer) > 0 AND CHARINDEX(@fb, equip_class) > 0;
        IF NOT (@t = @cAB AND @n = @n2 AND @n = CASE WHEN @cAB < 100 THEN @cAB ELSE 100 END)
            SET @txt += N'' two filters gave total '' + ISNULL(CAST(@t AS nvarchar(10)), N''NULL'') + N'' and '' + CAST(@n AS nvarchar(10)) + N'' row(s), '' + CAST(@n2 AS nvarchar(10)) + N'' of them satisfy both (independent count '' + CAST(@cAB AS nvarchar(10)) + N'');'';

        -- AND, not OR: the first filter matches, a second one nothing satisfies, so the list is empty
        SELECT @cA = COUNT(*) FROM app.vw_equipment_search WHERE CHARINDEX(@fa, manufacturer) > 0;
        SET @fJson = N''[{"column":"manufacturer","text":"'' + STRING_ESCAPE(@fa, ''json'') + N''"},{"column":"equip_class","text":"ZZZ-NO-SUCH-CLASS-ZZZ"}]'';
        EXEC sp_executesql @callF, @pdefF, @p_mode = ''SORTED'', @p_col = ''equipment_tag_number'', @p_text = N'''', @p_fac = N'''',
            @p_sort = ''equipment_number'', @p_dir = ''ASC'', @p_off = 0, @p_size = 100, @p_filters = @fJson,
            @o_total = @t OUTPUT, @o_more = @m OUTPUT, @o_trunc = @tr OUTPUT;
        SELECT @n = COUNT(*) FROM #r;
        IF NOT (@cA > 0 AND @t = 0 AND @n = 0)
            SET @txt += N'' a second filter nothing satisfies gave total '' + ISNULL(CAST(@t AS nvarchar(10)), N''NULL'') + N'' and '' + CAST(@n AS nvarchar(10)) + N'' row(s) while the first alone matches '' + CAST(@cA AS nvarchar(10)) + N'' (it behaves like OR);'';

        IF @txt = N'''' PRINT ''OK  R13 two column filters give exactly the heaters that satisfy both ('' + CAST(@cAB AS varchar(10)) + '' here), and a second filter nothing satisfies empties the list: AND'';
        ELSE BEGIN SET @fails += 1; PRINT ''FAIL R13 column filters:'' + @txt; END
    END
END TRY
BEGIN CATCH
    SET @fails += 1;
    PRINT ''FAIL R13 error '' + CAST(ERROR_NUMBER() AS varchar(12)) + '' on line '' + CAST(ERROR_LINE() AS varchar(12)) + '': '' + ERROR_MESSAGE();
END CATCH;

/* ---- R14 blanks, the limit of 20, blank values, literal characters --------------------------------------- */
DECLARE @blankJ TABLE (n int IDENTITY(1,1), j nvarchar(200));
INSERT INTO @blankJ (j) VALUES (N''''), (N''[]''), (N''[{"column":"manufacturer","text":"   "}]'');
DECLARE @chars TABLE (n int IDENTITY(1,1), c nvarchar(4));
INSERT INTO @chars (c) VALUES (N''%''), (N''_''), (N''[''), (N''\'');

BEGIN TRY
    SET @checks += 1;
    SET @txt = N'''';

    -- an empty list, [] and an entry with a blank text all mean "no filter"
    SET @k = 1; SELECT @kMax = COUNT(*) FROM @blankJ;
    WHILE @k <= @kMax
    BEGIN
        SELECT @fJson = j FROM @blankJ WHERE n = @k;
        EXEC sp_executesql @callF, @pdefF, @p_mode = ''SORTED'', @p_col = ''equipment_tag_number'', @p_text = N'''', @p_fac = N'''',
            @p_sort = ''equipment_number'', @p_dir = ''ASC'', @p_off = 0, @p_size = 100, @p_filters = @fJson,
            @o_total = @t OUTPUT, @o_more = @m OUTPUT, @o_trunc = @tr OUTPUT;
        IF NOT (@t = @allRows) SET @txt += N'' filters "'' + @fJson + N''" gave total '' + ISNULL(CAST(@t AS nvarchar(10)), N''NULL'') + N'', expected '' + CAST(@allRows AS nvarchar(10)) + N'';'';
        SET @k += 1;
    END

    -- 20 filters are accepted (the same column twenty times): the heaters whose manufacturer contains the letter a
    SET @fJson = N''['' + REPLICATE(CAST(N''{"column":"manufacturer","text":"a"},'' AS nvarchar(max)), 19) + N''{"column":"manufacturer","text":"a"}]'';
    SELECT @n = COUNT(*) FROM app.vw_equipment_search WHERE CHARINDEX(N''a'', manufacturer) > 0;
    EXEC sp_executesql @callF, @pdefF, @p_mode = ''SORTED'', @p_col = ''equipment_tag_number'', @p_text = N'''', @p_fac = N'''',
        @p_sort = ''equipment_number'', @p_dir = ''ASC'', @p_off = 0, @p_size = 100, @p_filters = @fJson,
        @o_total = @t OUTPUT, @o_more = @m OUTPUT, @o_trunc = @tr OUTPUT;
    IF NOT (@t = @n) SET @txt += N'' 20 filters gave total '' + ISNULL(CAST(@t AS nvarchar(10)), N''NULL'') + N'', expected '' + CAST(@n AS nvarchar(10)) + N'';'';

    -- a heater with a blank value in the filtered column never matches (here the tag)
    IF @ft IS NOT NULL
    BEGIN
        SET @fJson = N''[{"column":"equipment_tag_number","text":"'' + STRING_ESCAPE(@ft, ''json'') + N''"}]'';
        SELECT @n = COUNT(*) FROM app.vw_equipment_search WHERE CHARINDEX(@ft, equipment_tag_number) > 0;
        EXEC sp_executesql @callF, @pdefF, @p_mode = ''SORTED'', @p_col = ''equipment_tag_number'', @p_text = N'''', @p_fac = N'''',
            @p_sort = ''equipment_number'', @p_dir = ''ASC'', @p_off = 0, @p_size = 100, @p_filters = @fJson,
            @o_total = @t OUTPUT, @o_more = @m OUTPUT, @o_trunc = @tr OUTPUT;
        SELECT @n2 = COUNT(*) FROM #r WHERE equipment_tag_number IS NULL;
        IF NOT (@t = @n AND @n2 = 0) SET @txt += N'' tag filter gave total '' + ISNULL(CAST(@t AS nvarchar(10)), N''NULL'') + N'' (independent count '' + CAST(@n AS nvarchar(10)) + N'') and '' + CAST(@n2 AS nvarchar(10)) + N'' row(s) without a tag;'';
    END

    -- % _ [ and \ typed in a box are those characters, not wildcards or escapes
    SET @k = 1; SELECT @kMax = COUNT(*) FROM @chars;
    WHILE @k <= @kMax
    BEGIN
        SELECT @ch = c FROM @chars WHERE n = @k;
        SET @fJson = N''[{"column":"manufacturer","text":"'' + STRING_ESCAPE(@ch, ''json'') + N''"}]'';
        SELECT @n = COUNT(*) FROM app.vw_equipment_search WHERE CHARINDEX(@ch, manufacturer) > 0;
        EXEC sp_executesql @callF, @pdefF, @p_mode = ''SORTED'', @p_col = ''equipment_tag_number'', @p_text = N'''', @p_fac = N'''',
            @p_sort = ''equipment_number'', @p_dir = ''ASC'', @p_off = 0, @p_size = 100, @p_filters = @fJson,
            @o_total = @t OUTPUT, @o_more = @m OUTPUT, @o_trunc = @tr OUTPUT;
        IF NOT (@t = @n) SET @txt += N'' the character '' + @ch + N'' gave total '' + ISNULL(CAST(@t AS nvarchar(10)), N''NULL'') + N'', expected '' + CAST(@n AS nvarchar(10)) + N'';'';
        SET @k += 1;
    END

    IF @txt = N'''' PRINT ''OK  R14 blank entries and [] change nothing, 20 filters are accepted, a blank value never matches, and % _ [ \ are literal'';
    ELSE BEGIN SET @fails += 1; PRINT ''FAIL R14 column filters:'' + @txt; END
END TRY
BEGIN CATCH
    SET @fails += 1;
    PRINT ''FAIL R14 error '' + CAST(ERROR_NUMBER() AS varchar(12)) + '' on line '' + CAST(ERROR_LINE() AS varchar(12)) + '': '' + ERROR_MESSAGE();
END CATCH;

/* ---- R15 with the facility, with the older single text, and in MATCH mode ---------------------------------- */
BEGIN TRY
    IF @fa IS NULL OR @ft IS NULL
        PRINT ''INFO R15 no heater has both a manufacturer and a tag: the combined check is skipped'';
    ELSE
    BEGIN
        SET @checks += 1;
        SET @txt = N'''';
        SET @fJson = N''[{"column":"manufacturer","text":"'' + STRING_ESCAPE(@fa, ''json'') + N''"}]'';

        -- SORTED: facility + the older single text (the tag) + one column filter, all ANDed
        IF @fac IS NOT NULL
        BEGIN
            SELECT @n = COUNT(*) FROM app.vw_equipment_search
            WHERE superior_functional_location = @fac AND CHARINDEX(@ft, equipment_tag_number) > 0 AND CHARINDEX(@fa, manufacturer) > 0;
            EXEC sp_executesql @callF, @pdefF, @p_mode = ''SORTED'', @p_col = ''equipment_tag_number'', @p_text = @ft, @p_fac = @fac,
                @p_sort = ''equipment_number'', @p_dir = ''ASC'', @p_off = 0, @p_size = 100, @p_filters = @fJson,
                @o_total = @t OUTPUT, @o_more = @m OUTPUT, @o_trunc = @tr OUTPUT;
            IF NOT (@t = @n) SET @txt += N'' facility + text + filter gave total '' + ISNULL(CAST(@t AS nvarchar(10)), N''NULL'') + N'', expected '' + CAST(@n AS nvarchar(10)) + N'';'';
        END

        -- MATCH: the filter narrows the closest-match list too (compared when every tier is below its cap)
        SELECT @n = COUNT(*) FROM app.vw_equipment_search WHERE CHARINDEX(@ft, equipment_tag_number) > 0 AND CHARINDEX(@fa, manufacturer) > 0;
        EXEC sp_executesql @callF, @pdefF, @p_mode = ''MATCH'', @p_col = ''equipment_tag_number'', @p_text = @ft, @p_fac = N'''',
            @p_sort = ''equipment_number'', @p_dir = ''ASC'', @p_off = 0, @p_size = 100, @p_filters = @fJson,
            @o_total = @t OUTPUT, @o_more = @m OUTPUT, @o_trunc = @tr OUTPUT;
        SELECT @n2 = COUNT(*) FROM #r;
        IF @n <= 200 AND NOT (@t = @n AND @n2 = @n AND @tr = 0)
            SET @txt += N'' MATCH + filter gave total '' + ISNULL(CAST(@t AS nvarchar(10)), N''NULL'') + N'' and '' + CAST(@n2 AS nvarchar(10)) + N'' row(s), expected '' + CAST(@n AS nvarchar(10)) + N'';'';

        IF @txt = N'''' PRINT ''OK  R15 column filters are ANDed with the facility and the older single text, and narrow a MATCH list too'';
        ELSE BEGIN SET @fails += 1; PRINT ''FAIL R15 combined filters:'' + @txt; END
    END
END TRY
BEGIN CATCH
    SET @fails += 1;
    PRINT ''FAIL R15 error '' + CAST(ERROR_NUMBER() AS varchar(12)) + '' on line '' + CAST(ERROR_LINE() AS varchar(12)) + '': '' + ERROR_MESSAGE();
END CATCH;

/* ---- R16 refusals of a bad filter list -------------------------------------------------------------------------- */
DECLARE @badF TABLE (n int IDENTITY(1,1), label varchar(60), j nvarchar(4000), expected_error int);
INSERT INTO @badF (label, j, expected_error) VALUES
    (''not JSON'',                    N''this is not json'',                                                                  50017),
    (''an object, not a list'',       N''{"column":"manufacturer","text":"x"}'',                                              50017),
    (''entry without a text'',        N''[{"column":"manufacturer"}]'',                                                       50017),
    (''entry without a column'',      N''[{"text":"x"}]'',                                                                    50017),
    (''entry that is not an object'', N''["manufacturer"]'',                                                                  50017),
    (''column off the list (number)'',N''[{"column":"heat_duty_mmbtu_hr","text":"1"}]'',                                      50018),
    (''column off the list (id)'',    N''[{"column":"equipment_id","text":"1"}]'',                                            50018),
    (''column with SQL'',             N''[{"column":"manufacturer]; DROP TABLE app.app_setting; --","text":"x"}]'',           50018),
    (''text of 101 characters'',      N''[{"column":"manufacturer","text":"'' + REPLICATE(CAST(N''x'' AS nvarchar(max)), 101) + N''"}]'', 50019),
    (''21 filters'',                  N''['' + REPLICATE(CAST(N''{"column":"manufacturer","text":"a"},'' AS nvarchar(max)), 20) + N''{"column":"manufacturer","text":"a"}]'', 50019);

DECLARE @bj nvarchar(4000), @bjExpect int, @bjLabel varchar(60), @bjMax int = (SELECT COUNT(*) FROM @badF), @bjDone int = 0, @bjProblems nvarchar(1500) = N'''';
SET @i = 1;
SET @checks += 1;
WHILE @i <= @bjMax
BEGIN
    SELECT @bjLabel = label, @bj = j, @bjExpect = expected_error FROM @badF WHERE n = @i;
    SET @err = NULL;
    BEGIN TRY
        EXEC sp_executesql @callF, @pdefF, @p_mode = ''SORTED'', @p_col = ''equipment_tag_number'', @p_text = N'''', @p_fac = N'''',
            @p_sort = ''equipment_number'', @p_dir = ''ASC'', @p_off = 0, @p_size = 50, @p_filters = @bj,
            @o_total = @t OUTPUT, @o_more = @m OUTPUT, @o_trunc = @tr OUTPUT;
    END TRY
    BEGIN CATCH
        SET @err = ERROR_NUMBER();
    END CATCH;
    IF @err = @bjExpect SET @bjDone += 1;
    ELSE SET @bjProblems += N'' ['' + @bjLabel + N'': error '' + ISNULL(CAST(@err AS nvarchar(12)), N''none'') + N'', expected '' + CAST(@bjExpect AS nvarchar(12)) + N'']'';
    SET @i += 1;
END

IF OBJECT_ID(N''app.app_setting'', N''U'') IS NULL
    SET @bjProblems += N'' [app.app_setting is gone: the injection attempt may have worked]'';

IF @bjDone = @bjMax AND @bjProblems = N''''
    PRINT ''OK  R16 all '' + CAST(@bjMax AS varchar(10)) + '' bad filter lists are refused with the expected error number (50017 to 50019), including a column name that carries SQL'';
ELSE BEGIN SET @fails += 1; PRINT ''FAIL R16 filter refusals:'' + @bjProblems; END

DROP TABLE IF EXISTS #r;

IF @fails = 0 PRINT ''t_equipment_read RESULT: ALL '' + CAST(@checks AS varchar(10)) + '' CHECKS PASS'';
ELSE PRINT ''t_equipment_read RESULT: '' + CAST(@fails AS varchar(10)) + '' OF '' + CAST(@checks AS varchar(10)) + '' CHECK(S) FAILED'';
');

PRINT N'=== end of app2_2_read_procs_tests ===';
